// Accepts only wacrm 'message.received' deliveries and flattens them.
// Everything else (status updates, conversation.created) ends the run: n8n
// already answered 200 via the Webhook node's immediate-response mode.

const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;

  if (body?.event !== 'message.received') continue;
  const d = body.data ?? {};
  if (!d.conversation_id) continue;

  out.push({
    json: {
      deliveryId: body.id ?? '',
      conversationId: d.conversation_id,
      contactId: d.contact_id ?? '',
      whatsappMessageId: d.whatsapp_message_id ?? '',
      contentType: d.content_type ?? 'text',
      text: typeof d.text === 'string' ? d.text : '',
      occurredAt: body.occurred_at ?? new Date().toISOString(),
    },
  });
}

return out;

// Builds the transcript the model reads.
//
// The wacrm API returns messages NEWEST first; the model reads better in
// chronological order, so reverse. Both directions are kept — assessing
// risk in a sales conversation requires seeing what the staff said, not
// just the customer.

const MAX_CHARS = 6000;

return $input.all().map((item, i) => {
  const resp = item.json;
  const messages = Array.isArray(resp.data) ? resp.data : [];
  const event = $('Filter Event').itemMatching(i).json;
  const contactResp = $('Fetch Contact').itemMatching(i).json;
  const contact = contactResp.data ?? {};

  const lines = messages
    .slice()
    .reverse()
    .map((m) => {
      const who = m.direction === 'inbound' ? 'Customer' : 'Staff';
      const text = (m.content_text ?? m.text ?? '').toString().trim();
      const kind = m.content_type && m.content_type !== 'text' ? '[' + m.content_type + '] ' : '';
      return text || kind ? who + ': ' + kind + text : null;
    })
    .filter(Boolean);

  let transcript = lines.join('\n');
  if (transcript.length > MAX_CHARS) {
    transcript = '…' + transcript.slice(-MAX_CHARS);
  }
  if (!transcript) transcript = 'Customer: ' + (event.text || '(empty message)');

  return {
    json: {
      transcript,
      latestMessage: event.text,
      occurredAt: event.occurredAt,
      contactName: (contact.name ?? '').toString(),
      contactPhone: (contact.phone ?? '').toString(),
      conversationId: event.conversationId,
      deliveryId: event.deliveryId,
    },
  };
});

