// Maps the AI verdict onto the Firestore document the Flutter app reads.
// createdAt MUST be timestampValue — as a stringValue the app's
// Timestamp.toDate() yields null and cards show "Unknown time".

const ALLOWED = ['urgent', 'high', 'medium'];

return $input.all().map((item, i) => {
  let ai = item.json.output ?? item.json;
  if (typeof ai === 'string') {
    try { ai = JSON.parse(ai); } catch (e) { ai = {}; }
  }

  const ctx = $('Build Transcript').itemMatching(i).json;

  const rawPriority = String(ai.priority ?? '').trim().toLowerCase();
  const priority = ALLOWED.includes(rawPriority) ? rawPriority : 'medium';

  const nameParts = String(ctx.contactName ?? '').trim().split(/\s+/).filter(Boolean);
  const firstName = nameParts[0] ?? '';
  const lastName = nameParts.slice(1).join(' ');

  const digits = String(ctx.contactPhone ?? '').replace(/[^0-9]/g, '');
  const phone = digits ? '+' + digits : '';

  return {
    json: {
      shouldEscalate: ai.shouldEscalate === true || ai.shouldEscalate === 'true',
      firestore: {
        fields: {
          priority: { stringValue: priority },
          reason: { stringValue: String(ai.reason ?? '').slice(0, 500) },
          firstName: { stringValue: firstName },
          lastName: { stringValue: lastName },
          phone: { stringValue: phone },
          message: { stringValue: String(ctx.latestMessage ?? '').slice(0, 4000) },
          createdAt: { timestampValue: ctx.occurredAt || new Date().toISOString() },
        },
      },
    },
  };
});
